/// <summary>
///     AVA <c>init</c> method.
/// </summary>
public void init()
{
    kcs_KBVParameters = KCS_KBVParameters::find();
    if (!kcs_KBVParameters.RecId)
    {
        throw error("@SYS27512");
    }
}

/// <summary>
///     AVA <c>run</c> method.
/// </summary>
public void run()
{
    int                     nAnzBV;
    int                     nAnzActivities; 
    NDX_KBVJobProt          nDX_KBVJobProt;

    QueryBuildDataSource    qbds;
    Query                   q;

    #OCCRetryCount

    nAnzActivities = 0;

    nDX_KBVJobProt.createProt(NDX_KBVJob::KBV_ActivitySendlist, lJobMode);

    if (lJobMode)
    {
        q       = queryrun.query();
        qbds    = q.dataSourceTable(tablenum(KCS_KBVBuildingProjectTable));
        info("@NDX:NXACreateActivitiesBatch");
        info(strfmt("@NDX:NXAFilterSettingsDetails", qbds.toString()));
        info(strfmt("@SYS119858", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()))));
    }

    try
    {

        while (queryRun.next())
        {
            ttsbegin;
            kcs_KBVBuildingProjectTable = queryRun.get(tablenum(KCS_KBVBuildingProjectTable));

            if(!kcs_KBVBuildingProjectTable.isClosed())
            {
                //nur setzen wenn auch eine Aktivität erstellt wurde
                lSendActivity = false;

                nAnzActivities += this.createActivitiesV2();

                ++nAnzBV;
            }
            //offene Aktivitäten schliessen falls Zuständigkeit beendet
            this.closeActivities();

            ttscommit;
        }

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                if (conLen(this.parmProcessingInterval()) > 0)
                {
                    Error(strFmt("@NDX:NXABPUpdateConflictBatch",kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID));
                }
                else
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw;
        }
    }

    nDX_KBVJobProt.createProt(NDX_KBVJob::KBV_ActivitySendlist, lJobMode, false);

    if (lJobMode)
    {
        info(strfmt("@NDX:NXAEndCountBPNewActivities",  NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())),
                                                        nAnzBV,
                                                        nAnzActivities  )   );
    }
}

/// <summary>
///     AVA <c>createActivities</c> method.
///     2009: KCS_KBVActivitySendList.createActivities()
/// </summary>
/// <returns>
///     <c>int</c> as return value
/// </returns>
int createActivities()
{
    int retVal;

    KCS_KBVCompPrio             kcs_KBVCompPrio, kcs_KBVCompPrioTMP;
    KCS_KBVBPCompanySpecific    kcs_KBVBPCompanySpecific;
    HcmWorker                   locHCMWorker;
    smmActivities               smmActivities;
    smmActivities               smmActivities2;
    smmActivities               smmsmmActivitiesTMP;
    smmActivityParentLinkTable  smmActivityParentLinkTable;
    KCS_KBVRelationsToBV        kCS_KBVRelationsToBV;
    KCS_KBVRelations            kCS_KBVRelations;
    CustTable                   custTable;
    DirPartyTable               dirPartyTable;
    smmBusRelTable              smmBusRelTable;
    ContactPerson               contactPerson;

    HcmWorkerRecId              actWorkerId;
    HcmWorkerRecId              oldWorkerId;
    int                         nAnzNewActivities; 
    boolean                     lFirst;

    nAnzNewActivities   = 0;
    actWorkerId         = 0;
    oldWorkerId         = 0;

    // höchste Zuständigkeit je UK ermitteln
    while select crosscompany * 
    from    kcs_KBVBPCompanySpecific
    order by kcs_KBVCompPrio.Id
    where   kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID   == kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID
        join    kcs_KBVCompPrio
        where   kcs_KBVCompPrio.Company                         == kcs_KBVBPCompanySpecific.dataAreaId
    {
        actWorkerId = KCS_KBVResponsibilitiesTable::getHighestResponsibility(   kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID,
                                                                                kcs_KBVBPCompanySpecific.dataAreaId );
        if(actWorkerId)
        {
            changecompany(kcs_KBVBPCompanySpecific.dataAreaId)
            {
                //emplTable                   = null;
                locHCMWorker                = null;
                smmActivities               = null;
                smmActivityParentLinkTable  = null;

                select firstOnly * 
                from    locHCMWorker
                where   locHCMWorker.RecId              == actWorkerId
                    &&  locHCMWorker.NDX_KBVActivities  == true;

                if (locHCMWorker.RecId)
                {
                    smmActivities = KCS_KBVResponsibilitiesTable::activityAvail(kcs_KBVBuildingProjectTable.RecId, actWorkerId);

                    // prüfen, ob es für diesen Zuständigen für dieses BV schon eine Aktivität gibt
                    if (!smmActivities.RecId)
                    {
                        //hat die Zuständigkeit sich eventuell geändert und gibt es noch eine Aktivität für dieses Bauvorhaben?
                        select firstOnly smmActivityParentLinkTable
                        where   smmActivityParentLinkTable.ParentType     == smmActivityParentType::BuildingProject
                            &&  smmActivityParentLinkTable.RefRecId       == kcs_KBVBuildingProjectTable.RecId
                            join    smmActivities
                            where   smmActivities.ActivityNumber    == smmActivityParentLinkTable.ActivityNumber
                                &&  smmActivities.Category          == kcs_KBVParameters.KCS_KBVActivityCategory
                                &&  smmActivities.TypeId            == kcs_KBVParameters.KCS_KBVActivityTypeId;

                        if(!smmActivityParentLinkTable.recId)
                        {
                            // Erzeugen der neuen Aktivität
                            if (createActivities)
                            {
                                ttsbegin;

                                smmActivities.setActivityNum();
                                smmActivities.avaInitFromCommon(  kcs_KBVBuildingProjectTable,locHCMWorker.RecId);
                                smmActivities.AVABVInfoDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
                                smmActivities.Category          = kcs_KBVParameters.KCS_KBVActivityCategory;
                                smmActivities.TypeId            = kcs_KBVParameters.KCS_KBVActivityTypeId;
                                smmActivities.insert();
                                //KCS_KBVActivitiesForBP::createReference(    kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                //                                            smmActivities.ActivityNumber,
                                //                                            smmActivities.dataAreaId    );
                                ttscommit;

                                nAnzNewActivities++;


                                if (!lJobMode)
                                {
                                    info(strfmt("@NDX:NXANewActivityCreatedFor",    kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID,
                                                                                    kcs_KBVBPCompanySpecific.dataAreaId,
                                                                                    //emplTable.EmplId));
                                                                                    HCMWorker::find(locHCMWorker.RecId).name()  )   );
                                }
                            }
                        }
                        else
                        {
                            // umsetzen der neuen Zuständigkeit
                            if(createActivities)
                            {
                                oldWorkerId = smmActivities.ResponsibleWorker;
                                //Zuständigkeit hat sich geändert, Aktivität neuen Zuständigen zuweisen
                                /* obsolete and overwriiten method in 2009 possible solution with using System.IDisposable
                                */
                                smmActivities = KCS_KBVResponsibilitiesTable::activityAvail(kcs_KBVBuildingProjectTable.RecId,
                                                                                        oldWorkerId);
                                smmActivities.selectForUpdate(true);
                                smmActivities.ResponsibleWorker     = actWorkerId;
                                smmActivities.Closed                = NoYes::No;
                                smmActivities.AVABVInfoDate         = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
                                smmActivities.modifiedField(fieldnum(smmActivities, Closed));

                                if(smmActivities.validateWrite())
                                {
                                    ttsbegin;
                                    smmActivities.update();
                                    ttscommit;

                                    if (!lJobMode)
                                    {
                                        info(strfmt("@NDX:NXANewResponsibilityForActivity", kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID,
                                                                                            kcs_KBVBPCompanySpecific.dataAreaId,
                                                                                            //oldEmplId,
                                                                                            oldWorkerId,
                                                                                            //actEmplId));
                                                                                            actWorkerId));
                                    }
                                    nAnzNewActivities++;
                                }

                                lFirst = true;

                                //hat der Zuständige nun 2 die gleichen Aktivitäten?
                                while select crosscompany smmActivityParentLinkTable
                                order by kcs_KBVCompPrioTMP.Id
                                where   smmActivityParentLinkTable.ParentType   == smmActivityParentType::BuildingProject &&
                                        smmActivityParentLinkTable.RefRecId     == kcs_KBVBuildingProjectTable.RecId
                                    join    smmActivities2
                                    where   smmActivities2.ActivityNumber           == smmActivityParentLinkTable.ActivityNumber  &&
                                            smmActivities2.Category                 == kcs_KBVParameters.KCS_KBVActivityCategory  &&
                                            smmActivities2.TypeId                   == kcs_KBVParameters.KCS_KBVActivityTypeId    &&
                                            //smmActivities2.ResponsibleEmployee      == actEmplId
                                            smmActivities2.ResponsibleWorker        == actWorkerId
                                        join    kcs_KBVCompPrioTMP
                                        where   kcs_KBVCompPrioTMP.Company  == smmActivities2.dataAreaId
                                {
                                    changecompany(smmActivities2.dataAreaId)
                                    {
                                        if(!lFirst)
                                        {
                                            smmsmmActivitiesTMP = null;

                                            //smmsmmActivitiesTMP = KCS_KBVResponsibilitiesTable::activityAvail(kcs_KBVBuildingProjectTable.RecId, actEmplId, kcs_KBVBPCompanySpecific.dataAreaId);
                                            smmsmmActivitiesTMP = KCS_KBVResponsibilitiesTable::activityAvail(  kcs_KBVBuildingProjectTable.RecId,
                                                                                                                //actEmplId,
                                                                                                                actWorkerId,
                                                                                                                kcs_KBVBPCompanySpecific.dataAreaId );
                                            smmsmmActivitiesTMP.selectForUpdate(true);

                                            ttsbegin;
                                            smmsmmActivitiesTMP.delete();
                                            ttscommit;
                                        }
                                        else
                                        {
                                            lFirst = false;
                                        }
                                    }
                                }
                            }
                        }
                    }
                    else if(    smmActivities.RecId
                            &&  smmActivities.Closed) //if activity is closed check if the activity must be reopened
                    {
                        //if(     smmActivities.DoneByEmployee                                                !=  smmActivities.ResponsibleEmployee
                        if(     smmActivities.DoneByWorker                                                  !=  smmActivities.ResponsibleWorker
                            &&  smmActivities.actualEndDateTime(DateTimeUtil::getUserPreferredTimeZone())   <   smmActivities.modifiedDateTime  )
                        {
                            ttsbegin;

                            smmActivities.selectForUpdate(true);
                            //smmActivities.Closed = 0;
                            smmActivities.Closed = NoYes::No;
                            smmActivities.update();

                            ttscommit;
                        }
                    }

                    //Referenzen aktualisieren
                    select firstonly kCS_KBVRelationsToBV
                    order by kCS_KBVRelations.KCS_KBVSalesPriority desc
                    where   kCS_KBVRelationsToBV.KCS_KBVBuildingProjectID == kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID
                        join    kCS_KBVRelations
                        where   kCS_KBVRelationsToBV.KCS_KBVRelationID == kCS_KBVRelations.KCS_KBVRelationID;

                    if(kCS_KBVRelationsToBV)
                    {
                        custTable       = CustTable::findByPartyRecId(kCS_KBVRelationsToBV.DirPartyId);
                        dirPartyTable   = DirPartyTable::findRec(kCS_KBVRelationsToBV.DirPartyId);
                        smmBusRelTable  = smmBusRelTable::findByParty(kCS_KBVRelationsToBV.DirPartyId);
                        contactPerson   = kCS_KBVRelationsToBV.contactPerson();

                        if(dirPartyTable)
                        {
                            smmActivityParentLinkTable::updateOrCreateLink(smmActivities.ActivityNumber, smmActivityParentType::Organization, dirPartyTable.RecId);
                        }
                        if(custTable)
                        {
                            smmActivityParentLinkTable::updateOrCreateLink(smmActivities.ActivityNumber, smmActivityParentType::Customer, custTable.RecId);
                        }
                        if(smmBusRelTable)
                        {
                            smmActivityParentLinkTable::updateOrCreateLink(smmActivities.ActivityNumber, smmActivityParentType::BusRel, smmBusRelTable.RecId);
                        }
                        if(contactPerson)
                        {
                            smmActivityParentLinkTable::updateOrCreateLink(smmActivities.ActivityNumber, smmActivityParentType::ContactPerson, contactPerson.RecId);
                        }
                    }
                }
                else
                {
                    if (!lJobMode)
                    {
                        info(strfmt("@NDX:NXAEmployeeOptionCreateActivitiesNotActive",  kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID,
                                                                                        locHCMWorker.dataAreaId,
                                                                                        HcmWorker::find(actWorkerId).name() )   );
                    }
                }
            }
        }
    }
    retVal = nAnzNewActivities;

    return retVal;
}

/// <summary>
/// N.Freidenberger 16.09.2025
/// </summary>
/// <returns>int</returns>
int createActivitiesV2()
{
    int retVal;

    KCS_KBVCompPrio             kcs_KBVCompPrio;
    KCS_KBVBPCompanySpecific    kcs_KBVBPCompanySpecific;
    HcmWorker                   locHCMWorker;
    smmActivities               smmActivities;
    //smmActivities               smmActivities2;
    //smmActivities               smmsmmActivitiesTMP;
    smmActivityParentLinkTable  smmActivityParentLinkTable;
    KCS_KBVRelationsToBV        kCS_KBVRelationsToBV;
    KCS_KBVRelations            kCS_KBVRelations;
    CustTable                   custTable;
    DirPartyTable               dirPartyTable;
    smmBusRelTable              smmBusRelTable;
    ContactPerson               contactPerson;

    HcmWorkerRecId              actWorkerId;
    HcmWorkerRecId              oldWorkerId;
    int                         nAnzNewActivities;
    DataAreaId                  activityComp;
    //boolean                     lFirst;

    nAnzNewActivities   = 0;
    actWorkerId         = 0;
    oldWorkerId         = 0;

    if(!createActivities) 
    {
        return 0; //???
    }

    select firstonly crosscompany smmActivityParentLinkTable
        where   smmActivityParentLinkTable.ParentType   == smmActivityParentType::BuildingProject &&
            smmActivityParentLinkTable.RefRecId     == kcs_KBVBuildingProjectTable.RecId
        join    smmActivities
        where   smmActivities.ActivityNumber           == smmActivityParentLinkTable.ActivityNumber  &&
                smmActivities.Category                 == kcs_KBVParameters.KCS_KBVActivityCategory  &&
                smmActivities.TypeId                   == kcs_KBVParameters.KCS_KBVActivityTypeId    &&
                smmActivities.AVABVInfoDate      		> datenull();  //wird nur bei automatische Aktivitäten gesetzt



    if (smmActivities) //update existing activity
    {
        changecompany(smmActivities.DataAreaId)
        {
            oldWorkerId = smmActivities.ResponsibleWorker;
            actWorkerId = KCS_KBVResponsibilitiesTable::getHighestResponsibilityCrosscompany(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID).smmWorker;
            if (oldWorkerId != actWorkerId && actWorkerId)
            {
                smmActivities.selectForUpdate(true);
                smmActivities.ResponsibleWorker     = actWorkerId;
                smmActivities.Closed                = NoYes::No;
                smmActivities.AVABVInfoDate         = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

                smmActivities.modifiedField(fieldnum(smmActivities, Closed));

                if(smmActivities.validateWrite())
                {
                    ttsbegin;
                    smmActivities.update();
                    ttscommit;

                    if (conLen(processinginterval) == 0)
                    {
                        info(strfmt("@NDX:NXANewResponsibilityForActivity", kcs_KBVBPCompanySpecific.KCS_KBVBuildingProjectID,
                                                                        kcs_KBVBPCompanySpecific.dataAreaId,
                                                                        oldWorkerId,
                                                                        actWorkerId));
                    }
                    nAnzNewActivities++;
                }
            }
        }
        //end changecompany
    }
    else // create new activity
    {

        KCS_KBVResponsibilitiesTable        kbvResponsibilityTable;
        // höchste Zuständigkeit je UK ermitteln

        kbvResponsibilityTable = KCS_KBVResponsibilitiesTable::getHighestResponsibilityCrosscompany( kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);

        if (kbvResponsibilityTable)
        {
            actWorkerId = kbvResponsibilityTable.smmWorker;
            if(actWorkerId)
            {
                select firstonly kcs_KBVCompPrio 
                    order by Id asc;

                activityComp =   kcs_KBVCompPrio.ActivityCompany ? kcs_KBVCompPrio.ActivityCompany :   kbvResponsibilityTable.dataAreaId;
                //changecompany(kbvResponsibilityTable.dataAreaId)
                changecompany(activityComp)
                {
                    locHCMWorker                = null;
                    smmActivities               = null;
                    smmActivityParentLinkTable  = null;

                    select firstOnly *
                    from    locHCMWorker
                    where   locHCMWorker.RecId              == actWorkerId
                        &&  locHCMWorker.NDX_KBVActivities  == true;

                    if (locHCMWorker.RecId)
                    {
                        ttsbegin;

                        smmActivities.setActivityNum();
                        smmActivities.avaInitFromCommon(  kcs_KBVBuildingProjectTable,locHCMWorker.RecId);
                        smmActivities.AVABVInfoDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
                        smmActivities.Closed = NoYes::No;
                        smmActivities.Category      = kcs_KBVParameters.KCS_KBVActivityCategory;
                        smmActivities.TypeId        = kcs_KBVParameters.KCS_KBVActivityTypeId;
                        smmActivities.insert();
                        if (!KCS_KBVActivitiesForBP::exist(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID, smmActivities.ActivityNumber))
                        {
                            KCS_KBVActivitiesForBP::createReference(kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                                                    smmActivities.ActivityNumber,
                                                                    smmActivities.dataAreaId);
                        }
                        ttscommit;

                        nAnzNewActivities++;

                        if (!lJobMode)
                        {
                            info(strfmt("@NDX:NXANewActivityCreatedFor",    kbvResponsibilityTable.KCS_KBVBuildingProjectID,
                                                                            kbvResponsibilityTable.dataAreaId,
                                                                            //emplTable.EmplId));
                                                                            HCMWorker::find(locHCMWorker.RecId).name()  )   );
                        }
                    }
                }
            }
            else
            {
                if (!lJobMode)
                {
                    info(strfmt("@NDX:NXAEmployeeOptionCreateActivitiesNotActive",  kbvResponsibilityTable.KCS_KBVBuildingProjectID,
                                                                                    locHCMWorker.dataAreaId,
                                                                                    HcmWorker::find(actWorkerId).name() )   );
                }
            }
        }
    }
    // end create new activity

    if (smmActivities)
    {
        //Referenzen aktualisieren
        select firstonly kCS_KBVRelationsToBV
        order by kCS_KBVRelations.KCS_KBVSalesPriority desc
        where   kCS_KBVRelationsToBV.KCS_KBVBuildingProjectID == kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID
        join    kCS_KBVRelations
        where   kCS_KBVRelationsToBV.KCS_KBVRelationID == kCS_KBVRelations.KCS_KBVRelationID;

        if(kCS_KBVRelationsToBV)
        {
            custTable       = CustTable::findByPartyRecId(kCS_KBVRelationsToBV.DirPartyId);
            dirPartyTable   = DirPartyTable::findRec(kCS_KBVRelationsToBV.DirPartyId);
            smmBusRelTable  = smmBusRelTable::findByParty(kCS_KBVRelationsToBV.DirPartyId);
            contactPerson   = kCS_KBVRelationsToBV.contactPerson();

            if(dirPartyTable)
            {
                smmActivityParentLinkTable::updateOrCreateLink(smmActivities.ActivityNumber, smmActivityParentType::Organization, dirPartyTable.RecId);
            }
            if(custTable)
            {
                smmActivityParentLinkTable::updateOrCreateLink(smmActivities.ActivityNumber, smmActivityParentType::Customer, custTable.RecId);
            }
            if(smmBusRelTable)
            {
                smmActivityParentLinkTable::updateOrCreateLink(smmActivities.ActivityNumber, smmActivityParentType::BusRel, smmBusRelTable.RecId);
            }
            if(contactPerson)
            {
                smmActivityParentLinkTable::updateOrCreateLink(smmActivities.ActivityNumber, smmActivityParentType::ContactPerson, contactPerson.RecId);
            }
        }
    }
    retVal = nAnzNewActivities;
    return retVal;
}

/// <summary>
///     AVA <c>closeActivities</c> method.
/// </summary>
void closeActivities()
{
    smmActivities                   locSmmActivities, tmp_smmActivities;
    smmActivityParentLinkTable      locSmmActivityParentLinkTable;
    KCS_KBVResponsibilitiesTable    kCS_KBVResponsibilitiesTable;
    DataAreaId                      locDataAreaId;
    DataAreaId                      locDataAreaIdRico;
    container                       locBPCompanies;

    locDataAreaId       = curExt();
    locDataAreaIdRico   = kcs_KBVParameters.AVADataAreaIdRICO;

    if(strUpr(locDataAreaId) == strUpr(locDataAreaIdRico)) // Rico is actual company
    {
        locBPCompanies = [locDataAreaIdRico];
    }
    else
    {
        locBPCompanies = AVAKBVBuildingProjectHelper::getAllCompanies(true);
    }

    //alle offenen Aktivitäten zum BV prüfen
    while select crosscompany: locBPCompanies *
    from    locSmmActivityParentLinkTable
    where   locSmmActivityParentLinkTable.ParentType  == smmActivityParentType::BuildingProject
        &&  locSmmActivityParentLinkTable.RefRecId    == kcs_KBVBuildingProjectTable.RecId
        join    locSmmActivities
        where   locSmmActivities.ActivityNumber   == locSmmActivityParentLinkTable.ActivityNumber
            &&  locSmmActivities.TypeId           == kcs_KBVParameters.KCS_KBVActivityTypeId
            &&  locSmmActivities.Category         == kcs_KBVParameters.KCS_KBVActivityCategory
            &&  locSmmActivities.Closed           == NoYes::No
    {

        select firstonly crosscompany kCS_KBVResponsibilitiesTable
        where   kCS_KBVResponsibilitiesTable.KCS_KBVBuildingProjectID   == kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID
            &&  !kCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate
            &&  kCS_KBVResponsibilitiesTable.smmWorker                  == locSmmActivities.ResponsibleWorker;

        if(!kCS_KBVResponsibilitiesTable)
        {
            changecompany(locSmmActivities.dataAreaId)
            {
                tmp_smmActivities = null;

                select firstonly forupdate tmp_smmActivities
                where   tmp_smmActivities.RecId == locSmmActivities.RecId;

                if(tmp_smmActivities)
                {
                    tmp_smmActivities.Closed = NoYes::Yes;
                    tmp_smmActivities.modifiedField(fieldnum(smmActivities, Closed));

                    if(tmp_smmActivities.validateWrite())
                    {
                        ttsbegin;
                        tmp_smmActivities.write();
                        if(!lJobMode)
                        {
                            info(strfmt("@NDX:NXABPActivityClosed", kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID,
                                                                    tmp_smmActivities.ActivityNumber    )   );
                        }
                        ttscommit;
                    }
                }
            }
        }
    }
}
